-- Explicit local/test data load; never run against production.
\set ON_ERROR_STOP on
\getenv demo_password_hash DEMO_PASSWORD_HASH
\getenv channel1_key_hash CANAL1_KEY_HASH
\getenv channel2_key_hash CANAL2_KEY_HASH
BEGIN;
SELECT set_config('villaserena.demo_password_hash', :'demo_password_hash', true) AS ignored \gset
SELECT set_config('villaserena.channel1_key_hash', :'channel1_key_hash', true) AS ignored \gset
SELECT set_config('villaserena.channel2_key_hash', :'channel2_key_hash', true) AS ignored \gset
DO $validate$
DECLARE
  table_name text;
  populated boolean;
BEGIN
  IF current_setting('villaserena.demo_password_hash') !~ '^\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53}$' THEN
    RAISE EXCEPTION 'DEMO_PASSWORD_HASH must be a BCrypt hash';
  END IF;
  IF current_setting('villaserena.channel1_key_hash') !~ '^[0-9a-f]{64}$'
     OR current_setting('villaserena.channel2_key_hash') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Channel key hashes must be lowercase SHA-256 hex';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM flyway_schema_history WHERE version='29' AND success) THEN
    RAISE EXCEPTION 'Apply all schema migrations before loading local fixtures';
  END IF;

  PERFORM pg_advisory_xact_lock(590059);
  FOR table_name IN SELECT tablename FROM pg_tables
      WHERE schemaname='public' AND tablename<>'flyway_schema_history'
  LOOP
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I)', table_name) INTO populated;
    IF populated THEN
      RAISE EXCEPTION 'Local fixtures require empty business tables: % is populated', table_name;
    END IF;
  END LOOP;
END
$validate$;

     trade_name, legal_name, tax_id, tax_address)
